-- Generated by etl-chronology.mjs. Leaves all new content DRAFT until evidence review.
begin;
set local statement_timeout='240s';
set local lock_timeout='5s';
do $guard$ begin
  if exists(select 1 from pg_extension where extname='http') then
    raise exception 'Import requires temporary http extension; preserve existing installations';
  end if;
end $guard$;
create extension http with schema extensions;
select extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS','45000');
create temporary table _chron_raw(name text primary key, body jsonb) on commit drop;
do $download$
declare s record; r record;
begin
  for s in select * from (values {{SOURCES}}) as src(name,url,sha256,bytes) loop
    select * into r from extensions.http_get(s.url);
    if r.status<>200 or octet_length(r.content)<>s.bytes
      or encode(extensions.digest(convert_to(r.content,'UTF8'),'sha256'),'hex')<>s.sha256 then
      raise exception 'Chronology source integrity failure: %',s.name;
    end if;
    insert into _chron_raw values(s.name,r.content::jsonb);
    insert into public.chronology_sources(source_key,dataset,version,locator,sha256,license,attribution,raw_metadata)
    values('theographic:'||s.name||':'||{{COMMIT}},'Theographic Bible Metadata',{{COMMIT}},s.url,s.sha256,
      'CC BY-SA 4.0','Robert Rouse / Theographic; verse years: Ussher via Torrey; events: Floyd Nolen Jones, Acts: Todd Atwood',
      jsonb_build_object('file',s.name,'date_convention','ISO astronomical years; year zero is 1 BC','transformation','chronology metadata projection v1'))
    on conflict(source_key) do nothing;
  end loop;
end $download$;
insert into public.chronology_models(id,name,adam_year,resurrection_year,assumptions) values
 ('theographic-verse-v1','Theographic verse placements (Ussher)',-4003,33,
  '{"basis":"Approximate marginal verse years; not archaeological confirmation","chronology":"Ussher via Torrey Treasury of Scripture Knowledge","precision":"Source placement; a single year is not historical certainty"}'),
 ('theographic-events-v1','Theographic event associations (Jones)',-4003,30,
  '{"basis":"Event mentions are not automatically narrative setting dates","chronology":"Floyd Nolen Jones; Acts contributed by Todd Atwood","resurrection_year_assumption":30}')
on conflict(id) do nothing;
create temporary table _chron_verses on commit drop as
 select row->>'id' source_id, row->'fields' fields,
 (substring(row->'fields'->>'verseID',1,2))::integer book,
 (substring(row->'fields'->>'verseID',3,3))::integer chapter,
 (substring(row->'fields'->>'verseID',6,3))::integer verse
 from _chron_raw cross join lateral jsonb_array_elements(body) row where name='verses';
create unique index on _chron_verses(source_id);
create unique index on _chron_verses(book,chapter,verse);
create temporary table _chron_overrides(book integer,chapter integer,verse integer,source_id text,mapping jsonb) on commit drop;
insert into _chron_overrides values {{OVERRIDES}};
create temporary table _chron_map on commit drop as
 select v.id verse_id,s.source_id,jsonb_build_object('method','standard English reference; audited chapter boundaries',
   'correspondence','reference_only','source_ref',s.fields->>'osisRef') mapping
 from public.verses v join _chron_verses s on (s.book,s.chapter,s.verse)=(v.book,v.chapter,v.verse_nr)
 where v.verse_nr>0 and not exists(select 1 from _chron_overrides o where (o.book,o.chapter,o.verse)=(v.book,v.chapter,v.verse_nr))
 union all
 select v.id,o.source_id,o.mapping from _chron_overrides o
 join public.verses v on (v.book,v.chapter,v.verse_nr)=(o.book,o.chapter,o.verse);
create index on _chron_map(source_id);
do $check$ begin
 if (select count(distinct verse_id) from _chron_map)<> {{EXPECTED_MAPPED}} then
   raise exception 'Live passage/reference audit mismatch';
 end if;
end $check$;
insert into public.chronology_assertions(assertion_key,model_id,verse_id,source_id,axis,earliest_year,latest_year,preferred_year,
 precision,method,rationale,author,review_status,mapping)
select 'verse:'||m.verse_id||':'||s.source_id,'theographic-verse-v1',m.verse_id,src.id,'source_placement',
 (s.fields->>'yearNum')::integer,(s.fields->>'yearNum')::integer,(s.fields->>'yearNum')::integer,'source_year',
 'attributed_source_placement','Approximate source placement; context may describe an earlier or future event. A single source year does not establish historical precision.',
 'Theographic / Ussher via Torrey','source_import',m.mapping||jsonb_build_object('source_record',s.source_id,'source_ref',s.fields->>'osisRef','raw_year',s.fields->'yearNum')
from _chron_map m join _chron_verses s on s.source_id=m.source_id
cross join public.chronology_sources src
where src.source_key='theographic:verses:'||{{COMMIT}} and s.fields ? 'yearNum'
on conflict(assertion_key) do nothing;
insert into public.chronology_events(event_key,source_id,title,start_year,original_date,duration,range_flag,raw_metadata)
select row->>'id',s.id,row->'fields'->>'title',
 (regexp_match(row->'fields'->>'startDate','^(-?[0-9]+)(?:-[0-9]{2}-[0-9]{2})?$'))[1]::integer,
 row->'fields'->>'startDate',row->'fields'->>'duration',coalesce((row->'fields'->>'rangeFlag')::boolean,false),
 (row->'fields')-'verses'-'people (from verses)'
from _chron_raw r cross join lateral jsonb_array_elements(r.body) row
cross join public.chronology_sources s
where r.name='events' and s.source_key='theographic:events:'||{{COMMIT}}
on conflict(event_key) do nothing;
insert into public.chronology_event_links(event_id,verse_id,relationship,mapping)
select distinct e.id,m.verse_id,'mention',m.mapping from _chron_raw r
cross join lateral jsonb_array_elements(r.body) row
cross join lateral jsonb_array_elements_text(row->'fields'->'verses') ref
join _chron_map m on m.source_id=ref.value
join public.chronology_events e on e.event_key=row->>'id'
where r.name='events' and not exists(select 1 from public.chronology_event_links old where old.event_id=e.id and old.verse_id=m.verse_id)
on conflict do nothing;
insert into public.chronology_assertions(assertion_key,model_id,verse_id,event_id,source_id,axis,
 earliest_year,latest_year,preferred_year,precision,method,rationale,author,review_status,mapping)
select 'event:'||e.event_key||':'||l.verse_id,'theographic-events-v1',l.verse_id,e.id,e.source_id,'mentioned_event',
 e.start_year,e.start_year,e.start_year,case when e.original_date ~ '^[0-9]{4}-' then 'source_calendar_day' else 'source_year' end,
 'event_start_association','The source links this verse to an event. This is the event start, not necessarily the date of the verse setting or of its composition.',
 'Theographic / Jones; Acts: Atwood','source_import',l.mapping||jsonb_build_object('source_event',e.event_key,'duration',e.duration,'range_flag',e.range_flag,'original_date',e.original_date)
from public.chronology_event_links l join public.chronology_events e on e.id=l.event_id
on conflict(assertion_key) do nothing;
do $check$ begin
 if (select count(*) from public.chronology_events)<>450 then raise exception 'Event import mismatch'; end if;
end $check$;
drop extension http;
analyze public.chronology_assertions;
analyze public.chronology_event_links;
commit;
